        var ex = await Assert.ThrowsAsync<OAuth2ServerException>(() =>
            manager.GetAccessTokenAsync(
                new Uri("https://auth.example.com/token"),
                new Dictionary<string, string> { ["grant_type"] = "client_credentials" },
