    {
        // After invalidation, 10 concurrent callers must coalesce into exactly
        // ONE additional HTTP call (single-flight), all observing the same
        // freshly fetched token.
        var client = new CountingNumberingApiClient();

        var manager = new OAuth2TokenManager();
        manager.SetApiClient(client);

        var parameters = new Dictionary<string, string> { ["grant_type"] = "client_credentials" };
        var tokenUrl = new Uri("https://auth.example.com/token");

        string first = await manager.GetAccessTokenAsync(
            tokenUrl,
            parameters,
            cancellationToken: TestContext.Current.CancellationToken
        );
        Assert.Equal("tok1", first);
        Assert.Equal(1, client.CallCount);

        manager.InvalidateAccessToken();

        Task<string>[] tasks = new Task<string>[10];
        for (int i = 0; i < tasks.Length; i++)
        {
            tasks[i] = manager.GetAccessTokenAsync(
                tokenUrl,
                parameters,
                cancellationToken: TestContext.Current.CancellationToken
            );
        }
        string[] tokens = await Task.WhenAll(tasks);

        // Exactly one additional network call (CallCount went 1 -> 2).
        Assert.Equal(2, client.CallCount);
        foreach (string t in tokens)
        {
            Assert.Equal("tok2", t);
        }
    }

    private sealed class CountingNumberingApiClient : IApiClient
    {
        private int _callCount;

        public int CallCount => _callCount;

        public async Task<ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body
        )
        {
            int n = System.Threading.Interlocked.Increment(ref _callCount);
            // Hold the request in flight so concurrent callers pile up behind
            // the single-flight lock.
            await Task.Delay(50).ConfigureAwait(false);
            return new ApiHttpResponse(
                200,
                "{\"access_token\":\"tok" + n + "\",\"expires_in\":3600}",
                new Dictionary<string, string>()
            );
        }
    }

